mapper.select:
select aaa.* from (
UNION ALL
) aaa left join SYS_DATADICT_LIST sdl on aaa.ENTRUSTSTATUS=sdl.ITEM_CODE and sdl.DICT_CODE='ENTRUST_STATUS' order by sdl.ORDER_NO, aaa.entrustId DESC

mapper.sql:
SELECT T7.PAY_TYPE etrPayType, T8.BID_PRIN_AMT bidPriceTotal, T5.WIN_PRIN_AMT winPriceTotal, T1.ENTRUST_DATE entrustDate, t8.IS_WIN isWin, t8.BID_PRICE bidPrice, t5.WIN_PRICE winPriceStr, T1.ENTRUST_ID ENTRUSTID, T1.ENTRUST_STATUS ENTRUSTSTATUS, T12.REAL_NAME INVMANAGERID, T1.PORTFOLIO_ID PORTFOLIOID, T2.PORTFOLIO_NAME PORTFOLIONAME, T1.FINPROD_ID FINPRODID, T3.FINPROD_MARKET_ID FINPRODMARKETID, T3.FINPROD_ABBR FINPRODABBR, T3.FINPROD_NAME FINPRODNAME, T1.PS PS, T1.TRADE_MARKET TRADEMARKET, T1.TRADE_PLAT TRADEPLAT, T1.TRADE_MARKET_MODE TRADEMARKETMODE, T1.ENTRUST_NUM * 100 ENTRUSTNUM, T1.CCY CCY, T1.VDATE VDATE, T1.MDATE MDATE, T1.REMARK REMARK, T1.INV_AIM INVAIM, T7.SETTLE_SPREED SETTLESPREED, T7.ASSET_TYPE1 ASSETTYPE1,
T7.ASSET_TYPE_10 assetType10, T7.ASSET_TYPE_11 assetType11
,'' nextUser FROM ETR_ENTRUST T1 LEFT JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID LEFT JOIN PTL_PORTFOLIO_AUTHORITY T11 ON T11.PORTFOLIO_ID = T2.PORTFOLIO_ID AND T11.USER_ID = #{userId} LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T4 ON T4.FINPROD_ID = T3.FINPROD_ID LEFT JOIN (SELECT ORDPRICE.ENTRUST_ID, SUM(ORDPRICE.WIN_PRIN_AMT) WIN_PRIN_AMT,
LISTAGG( CASE WHEN ORDPRICE.WIN_PRICE IS NULL THEN NULL ELSE ORDPRICE.WIN_PRICE * 100 || '%' END, ',') WITHIN GROUP (order by (ORDPRICE.WIN_PRICE)) WIN_PRICE FROM BID_ORDER_BID_PRICE ORDPRICE GROUP BY ORDPRICE.ENTRUST_ID) T5 ON T5.ENTRUST_ID = T1.ENTRUST_ID LEFT JOIN (SELECT T9.ENTRUST_ID, SUM(T9.BID_PRIN_AMT) BID_PRIN_AMT , T10.BID_ID, T10.IS_WIN IS_WIN2,
LISTAGG( T9.BID_PRICE * 100 ||'%', ',') WITHIN GROUP (order by (T9.BID_PRICE * 100)) BID_PRICE, CASE WHEN T10.BID_ID IS NULL THEN '01' WHEN T10.TRADE_ID IS NOT NULL THEN '05' WHEN T10.IS_WIN IS NOT NULL THEN
DECODE(T10.IS_WIN,#{YES_OR_NO_Y}, '04', #{YES_OR_NO_N},'03',T10.IS_WIN)
ELSE '02' END IS_WIN FROM ETR_ENTRUST_BID_PRICE T9 LEFT JOIN BID_ORDER_BID_PRICE T10 ON T10.ENTRUST_ID = T9.ENTRUST_ID AND T10.BID_PRICE = T9.BID_PRICE GROUP BY T9.ENTRUST_ID, T10.BID_ID, T10.IS_WIN,T10.TRADE_ID ) T8 ON T8.ENTRUST_ID = T1.ENTRUST_ID LEFT JOIN ETR_ENTRUST_ADD T7 ON T1.ENTRUST_ID = T7.ENTRUST_ID LEFT JOIN SYS_USER T12 ON T1.INV_MANAGER_ID = T12.USER_NAME
AND T1.FINPROD_TYPE2 =#{bond}
AND (T1.PORTFOLIO_ID IN
null) OR T1.PORTFOLIO_ID in (
#{prot,jdbcType=VARCHAR}
OR T2.PARENT_PORTFOLIO_ID IN
null) OR T2.PARENT_PORTFOLIO_ID in (
#{prot,jdbcType=VARCHAR}
)
AND T1.CCY = #{ccy}
AND (T3.FINPROD_MARKET_ID like concat('%',concat(#{finprodId},'%')) or T3.FINPROD_ABBR like concat('%',concat(#{finprodId},'%')))
AND T1.TRADE_MARKET=#{tradeMarket}
AND T1.TRADE_PLAT=#{tradePlat}
AND T1.PS=#{ps}
AND T1.VDATE >=to_date(#{startDate},'yyyy-MM-dd')
AND T1.MDATE <=to_date(#{endDate},'yyyy-MM-dd')
AND T1.ENTRUST_DATE >=to_date(#{bidStartDate},'yyyy-MM-dd')
AND T1.ENTRUST_DATE <=to_date(#{bidEndDate},'yyyy-MM-dd')
AND T7.ASSET_TYPE1 in
#{item}
AND T1.ENTRUST_STATUS = #{entrustStatus}
AND T8.IS_WIN = #{bidStatus}
AND nvl(T1.TRADE_MARKET, T3.TRADE_MARKET) in
#{currTradeMarket}

SELECT T7.PAY_TYPE etrPayType, T8.BID_PRIN_AMT bidPriceTotal, T5.WIN_PRIN_AMT winPriceTotal, T1.ENTRUST_DATE entrustDate, t8.IS_WIN isWin, t8.BID_PRICE bidPrice, t5.WIN_PRICE winPriceStr, T1.ENTRUST_ID ENTRUSTID, '08' ENTRUSTSTATUS, T12.REAL_NAME INVMANAGERID, T1.PORTFOLIO_ID PORTFOLIOID, T2.PORTFOLIO_NAME PORTFOLIONAME, T1.FINPROD_ID FINPRODID, T3.FINPROD_MARKET_ID FINPRODMARKETID, T3.FINPROD_ABBR FINPRODABBR, T3.FINPROD_NAME FINPRODNAME, T1.PS PS, T1.TRADE_MARKET TRADEMARKET, T1.TRADE_PLAT TRADEPLAT, T1.TRADE_MARKET_MODE TRADEMARKETMODE, T1.ENTRUST_NUM * 100 ENTRUSTNUM, T1.CCY CCY, T1.VDATE VDATE, T1.MDATE MDATE, T1.REMARK REMARK, T1.INV_AIM INVAIM, T7.SETTLE_SPREED SETTLESPREED, T7.ASSET_TYPE1 ASSETTYPE1,
T7.ASSET_TYPE_10 assetType10, T7.ASSET_TYPE_11 assetType11
,SWBL.NEXT_USER nextUser FROM WFL_ETR_ENTRUST T1 LEFT JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID LEFT JOIN PTL_PORTFOLIO_AUTHORITY T11 ON T11.PORTFOLIO_ID = T2.PORTFOLIO_ID AND T11.USER_ID = #{userId} LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T4 ON T4.FINPROD_ID = T3.FINPROD_ID LEFT JOIN (SELECT ORDPRICE.ENTRUST_ID, SUM(ORDPRICE.WIN_PRIN_AMT) WIN_PRIN_AMT,
LISTAGG( CASE WHEN ORDPRICE.WIN_PRICE IS NULL THEN NULL ELSE ORDPRICE.WIN_PRICE * 100 || '%' END, ',') WITHIN GROUP (order by (ORDPRICE.WIN_PRICE)) WIN_PRICE FROM BID_ORDER_BID_PRICE ORDPRICE GROUP BY ORDPRICE.ENTRUST_ID) T5 ON T5.ENTRUST_ID = T1.ENTRUST_ID LEFT JOIN (SELECT T9.ENTRUST_ID, SUM(T9.BID_PRIN_AMT) BID_PRIN_AMT , T10.BID_ID, T10.IS_WIN IS_WIN2,
LISTAGG( T9.BID_PRICE * 100 ||'%', ',') WITHIN GROUP (order by (T9.BID_PRICE * 100)) BID_PRICE, CASE WHEN T10.BID_ID IS NULL THEN '01' WHEN T10.TRADE_ID IS NOT NULL THEN '05' WHEN T10.IS_WIN IS NOT NULL THEN
DECODE(T10.IS_WIN,#{YES_OR_NO_Y}, '04', #{YES_OR_NO_N},'03',T10.IS_WIN)
ELSE '02' END IS_WIN FROM ETR_ENTRUST_BID_PRICE T9 LEFT JOIN BID_ORDER_BID_PRICE T10 ON T10.ENTRUST_ID = T9.ENTRUST_ID AND T10.BID_PRICE = T9.BID_PRICE GROUP BY T9.ENTRUST_ID, T10.BID_ID, T10.IS_WIN,T10.TRADE_ID ) T8 ON T8.ENTRUST_ID = T1.ENTRUST_ID LEFT JOIN WFL_ETR_ENTRUST_ADD T7 ON T1.ENTRUST_ID = T7.ENTRUST_ID LEFT JOIN SYS_USER T12 ON T1.INV_MANAGER_ID = T12.USER_NAME LEFT JOIN SYS_WFL_BUSINESS_LIST SWBL ON SWBL.SEQ_NO = T1.WORKFLOW_ID and SWBL.PROCESS_STATE != 'END'
AND T1.FINPROD_TYPE2 =#{bond}
AND (T1.PORTFOLIO_ID IN
null) OR T1.PORTFOLIO_ID in (
#{prot,jdbcType=VARCHAR}
OR T2.PARENT_PORTFOLIO_ID IN
null) OR T2.PARENT_PORTFOLIO_ID in (
#{prot,jdbcType=VARCHAR}
)
AND T1.CCY = #{ccy}
AND (T3.FINPROD_MARKET_ID like concat('%',concat(#{finprodId},'%')) or T3.FINPROD_ABBR like concat('%',concat(#{finprodId},'%')))
AND T1.TRADE_MARKET=#{tradeMarket}
AND T1.TRADE_PLAT=#{tradePlat}
AND T1.PS=#{ps}
AND T1.VDATE >=to_date(#{startDate},'yyyy-MM-dd')
AND T1.MDATE <=to_date(#{endDate},'yyyy-MM-dd')
AND T1.ENTRUST_DATE >=to_date(#{bidStartDate},'yyyy-MM-dd')
AND T1.ENTRUST_DATE <=to_date(#{bidEndDate},'yyyy-MM-dd')
AND T7.ASSET_TYPE1 in
#{item}
AND T8.IS_WIN = #{bidStatus}
AND nvl(T1.TRADE_MARKET, T3.TRADE_MARKET) in
#{currTradeMarket}

mapper.select:
SELECT T1.PORTFOLIO_ID code, T1.PORTFOLIO_ID name, T1.PORTFOLIO_NAME shortName, T1.PORTFOLIO_ID hidCode FROM PTL_PORTFOLIO T1 INNER JOIN PTL_PORTFOLIO_AUTHORITY T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID AND T2.USER_ID = #{userId}
T1.PORTFOLIO_ID like concat('%',concat(#{param},'%')) or T1.PORTFOLIO_NAME like concat('%',concat(#{param},'%'))
AND T1.PORTFOLIO_TYPE = #{portType}

SELECT FINPROD_MARKET_ID code, FINPROD_MARKET_ID name, FINPROD_ABBR shortName, FINPROD_ID hidCode FROM FIN_PRODUCT
FINPROD_TYPE2 = #{assestType}
AND (FINPROD_MARKET_ID like concat('%',concat(#{param},'%')) or FINPROD_ABBR like concat('%',concat(#{param},'%')))
AND TRADE_MARKET in
#{currTradeMarket}

SELECT distinct T1.PORTFOLIO_ID id, T1.PORTFOLIO_NAME text, T1.PROFIT_TYPE object FROM PTL_PORTFOLIO T1 INNER JOIN PTL_PORTFOLIO_AUTHORITY T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID
and T2.USER_ID = #{userId}
and T1.PORTFOLIO_ID = #{initValue}
and (T1.PORTFOLIO_ID like concat('%',concat(#{search},'%')) or T1.PORTFOLIO_NAME like concat('%',concat(#{search},'%')) )
AND T1.PORTFOLIO_TYPE IN (#{portType}, #{portType1})

sql.where:
T1.FINPROD_TYPE2 = #{assestType}

	and T1.FINPROD_MARKET_ID = #{initValue}


	and (T1.FINPROD_MARKET_ID like concat('%',concat(#{search},'%'))
	or T1.FINPROD_NAME like concat('%',concat(#{search},'%')))

mapper.select:
SELECT T1.ENTRUST_ID entrustId, T1.PORTFOLIO_ID portfolioId, T1.VDATE vdate, T1.MDATE mdate, T1.ENTRUST_DATE entrustDate, T6.ASSET_TYPE1 assetType1,
T6.ASSET_TYPE_10 assetType10, T6.ASSET_TYPE_11 assetType11,
T1.CCY ccy, T1.FINPROD_ID finprodId, T3.FINPROD_MARKET_ID finprodMarketId, T3.FINPROD_NAME finprodName, T1.TRADE_MARKET tradeMarket, T1.INV_AIM invAim, T1.PRO_AVAILABLE_CASH proAvailableCash, T1.ACC_AVAILABLE_CASH accAvailableCash, T1.REMARK remark, T1.COUNTER_ID counterId, T1.COUNTER_TRADER counterTrader, T1.CONTACT_INFO contactInfo, T2.TRADER trader, T1.INV_MANAGER_ID invManagerId, T6.PAY_TYPE etrPayType, T6.PAYMENT_DATE paymentDate, T6.LISTING_DATE listingDate, T6.MAIN_CONSIGNEE mainConsignee, T6.BIDDING_RANGE biddingRange , '' businessModel, mci.CUSTOMER_NAME mainConsigneeValue FROM WFL_ETR_ENTRUST T1 LEFT JOIN ETR_DISTRIBUTE T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID AND T3.FINPROD_TYPE2 =#{bond} LEFT JOIN WFL_ETR_ENTRUST_ADD T6 ON T1.ENTRUST_ID = T6.ENTRUST_ID LEFT JOIN MST_CUSTOMER_INFO mci ON mci.CUSTOMER_ID = T6.main_consignee AND mci.IS_SALER = 'Y'
T1.PORTFOLIO_ID=#{portfolioId}
AND T1.FINPROD_ID = #{finprodId}
AND T1.ENTRUST_ID = #{entrustId}
union all SELECT T1.ENTRUST_ID entrustId, T1.PORTFOLIO_ID portfolioId, T1.VDATE vdate, T1.MDATE mdate, T1.ENTRUST_DATE entrustDate, T6.ASSET_TYPE1 assetType1,
T6.ASSET_TYPE_10 assetType10, T6.ASSET_TYPE_11 assetType11,
T1.CCY ccy, T1.FINPROD_ID finprodId, T3.FINPROD_MARKET_ID finprodMarketId, T3.FINPROD_NAME finprodName, T1.TRADE_MARKET tradeMarket, T1.INV_AIM invAim, T1.PRO_AVAILABLE_CASH proAvailableCash, T1.ACC_AVAILABLE_CASH accAvailableCash, T1.REMARK remark, T1.COUNTER_ID counterId, T1.COUNTER_TRADER counterTrader, T1.CONTACT_INFO contactInfo, T2.TRADER trader, T1.INV_MANAGER_ID invManagerId, T6.PAY_TYPE etrPayType, T6.PAYMENT_DATE paymentDate, T6.LISTING_DATE listingDate, T6.MAIN_CONSIGNEE mainConsignee, T6.BIDDING_RANGE biddingRange , T1.BUSINESS_MODEL businessModel, mci.CUSTOMER_NAME mainConsigneeValue FROM ETR_ENTRUST T1 LEFT JOIN ETR_DISTRIBUTE T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID AND T3.FINPROD_TYPE2 =#{bond} LEFT JOIN ETR_ENTRUST_ADD T6 ON T1.ENTRUST_ID = T6.ENTRUST_ID LEFT JOIN MST_CUSTOMER_INFO mci ON mci.CUSTOMER_ID = T6.main_consignee AND mci.IS_SALER = 'Y'
T1.PORTFOLIO_ID=#{portfolioId}
AND T1.FINPROD_ID = #{finprodId}
AND T1.ENTRUST_ID = #{entrustId}

	SELECT ENTRUST_ID ENTRUSTID, BID_PRICE * 100 BIDPRICE, BID_PRIN_AMT BIDPRINAMT
  FROM ETR_ENTRUST_BID_PRICE
 WHERE ENTRUST_ID = #{entrustId}

SELECT CUSTOMER_ID id, CUSTOMER_NAME text FROM MST_CUSTOMER_INFO WHERE IS_SALER = #{YESORNO_YES, jdbcType = VARCHAR}
AND( CUSTOMER_NAME LIKE CONCAT(CONCAT('%',#{search}),'%') OR CUSTOMER_ABBR LIKE CONCAT(CONCAT('%',#{search}),'%'))
AND( CUSTOMER_NAME LIKE CONCAT(CONCAT('%',#{initValue}),'%') OR CUSTOMER_ABBR LIKE CONCAT(CONCAT('%',#{initValue}),'%') OR CUSTOMER_ID LIKE CONCAT(CONCAT('%',#{initValue}),'%'))
